fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since the problem guarantees both vectors have the same length,
    // we can safely iterate paired elements by index.
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x | y)
        .collect()
}